// Delete a comment by setting deletedAt and keeping the row.
// Source: Okto Neuron, team vault, policy-soft-delete.md (bytes 0-194).
// Only the author may delete. The lookup filters by author, so a comment owned by someone else
// is not found and gets 404. The team vault gives no 403 for this case (code-comment-ownership.md,
// follow-up answer), so there is no 403 branch.
export const deleteComment = async (id: number, userId: number) => {
  const comment = await prisma.comment.findFirst({
    where: {
      id,
      deletedAt: null,
      author: {
        id: userId,
      },
    },
    select: {
      author: {
        select: {
          id: true,
          username: true,
        },
      },
    },
  });

  if (!comment) {
    throw new HttpException(404, {});
  }

  await prisma.comment.update({
    where: {
      id,
    },
    data: {
      deletedAt: new Date(),
    },
  });
